insert into public.academy_course_structures
    (app_slug, tier, structure, content_version)
insert into public.academy_quiz_questions
    (app_slug, tier, scope, module_key, ord, prompt, options, answer_index, explanation)
values
  ('joa', 'beginner', 'module', 'm01-what-a-joint-operating-agreement-fixes', 1, 'Which of these texts does the course quote word for word, with its citation?', '["The AIPN model joint operating agreement, whose clauses the industry adapts more than any other form.", "The COPAS accounting procedures, for their overhead scale and the timing of each cash call.", "The Norwegian joint operating agreement, from its unofficial English translation of the 2007 text.", "The AAPL forms, for the duties of the operator and the consent rules of the non-operators."]'::jsonb, 2, 'The Norwegian agreement is a public text, quoted with its citation from the Wayback Machine capture of 26 May 2024. The AIPN model joint operating agreement, the COPAS accounting procedures and the AAPL forms are licensed, so the course teaches their ideas by concept only and quotes none of them.'),
  ('joa', 'beginner', 'module', 'm01-what-a-joint-operating-agreement-fixes', 2, 'How does the course cite the Petroleum Industry Act 2021 (Act No. 6) when it names the Act''s edition?', '["Official Gazette No. 142, Vol. 108, 27 August 2021.", "Official Gazette No. 108, Vol. 142, 27 August 2021, with the volume and number as the gazette prints them.", "Official Gazette No. 142, Vol. 108, 27 February 2007, the date the Act''s joint venture rules were first printed.", "Act No. 6, cited from the Wayback Machine capture of 26 May 2024, because the gazette answered a bot check."]'::jsonb, 0, 'The sources table gives the Act as Official Gazette No. 142, Vol. 108, 27 August 2021. The number and the volume are not interchangeable, so 108 and 142 swapped name a different gazette. 27 February 2007 is the date on the Norwegian agreement''s PDF, and the Wayback capture of 26 May 2024 is how the course reads the Norwegian agreement, whose live copy answered the bot check.'),
  ('joa', 'beginner', 'module', 'm01-what-a-joint-operating-agreement-fixes', 3, 'On what date was each text in the course''s sources table read?', '["26 May 2024, the date of the Wayback Machine capture the Norwegian agreement is cited from.", "27 August 2021, the date of the Act''s gazette.", "27 February 2007, the date printed on the Norwegian agreement, the oldest text in the table.", "2026-09-26, the same date for every text in the table."]'::jsonb, 3, 'Every text in the sources table was read on 2026-09-26, and the table prints that date against each one. 26 May 2024 is the date of the Norwegian agreement''s archived capture, 27 August 2021 the date of the Act''s gazette and 27 February 2007 the date on the Norwegian PDF: each is an edition date, and none is a date the course read a text.'),
  ('joa', 'beginner', 'module', 'm01-what-a-joint-operating-agreement-fixes', 4, 'Why does the course cite the Norwegian agreement from a Wayback Machine capture?', '["The ministry withdrew the English translation in 2024, so the archived capture is the last copy.", "The live regjeringen.no copy answered a bot check with HTTP 403 on the date it was read.", "The capture holds the official Norwegian text, which the course then translates for itself.", "The regjeringen.no copy is licensed, so only an archived copy may be quoted in a course."]'::jsonb, 1, 'The sources table says the live regjeringen.no copy answered a bot check with HTTP 403 on 2026-09-26, so the text is cited from the capture of 26 May 2024. The text is an unofficial English translation, and the course translates nothing itself. It is a public text: the licensed texts are the AIPN, COPAS and AAPL forms.'),
  ('joa', 'beginner', 'module', 'm01-what-a-joint-operating-agreement-fixes', 5, 'What does the course say about a public worked schedule for a cash call reconciliation or for an overhead scale applied to figures?', '["The Kenya Model PSC 2015 prints one, and the course copies its cash call figures.", "The research found none, so those figures are the Norwegian clause arithmetic run by the engine.", "World Bank Briefing Note 8 prints one for overhead, which the panel runs.", "OpenOil prints one, and the course teaches it with the printed 11.75 corrected to the engine''s figure."]'::jsonb, 1, 'The validation record, quoted in the course, found no public text that prints a worked schedule for a cash call over/under reconciliation or an overhead scale applied to figures, so those figures are the stated clause arithmetic of the Norwegian agreement run by the engine. The Kenya model prints cash call clauses and no schedule, Briefing Note 8 prints a PSC illustration, and OpenOil''s 11.75 belongs to a state participation example that is taught as a printed arithmetic error.'),
  ('joa', 'beginner', 'module', 'm01-what-a-joint-operating-agreement-fixes', 6, 'How does the fixture file of the Ekene joint venture describe itself, in its own words?', '["Anonymised books of a Nigerian shallow water joint venture, with each partner''s name removed.", "A worked schedule published with the Norwegian agreement, restated in US$ for the course''s use.", "A regulator''s model case for PIA s.85(4), with the four parties relabelled EKO, PA, PB and NOC.", "SYNTHETIC teaching data for the Ekene field (ours). No real company, contract, budget, price or regulator decision."]'::jsonb, 3, 'The fixture is labelled SYNTHETIC in the file, written by a stated script for this platform, and the course quotes that label verbatim. No real joint venture''s books are used, no public text prints a worked schedule of this kind for the Norwegian agreement, and no regulator decision appears in the data.'),
  ('joa', 'beginner', 'module', 'm01-what-a-joint-operating-agreement-fixes', 7, 'Which participating interests and which carry does the Ekene fixture state?', '["EKO 40.000000, PA 25.000000, PB 15.000000 and NOC 20.000000, with NOC carried 100 percent by pro rata carriers.", "EKO 50.000000, PA 31.250000, PB 18.750000 and NOC 0.000000, with no carry stated anywhere in the file.", "EKO 40.000000, PA 25.000000, PB 15.000000 and NOC 20.000000, with NOC carried half, in stated shares.", "EKO 40.000000, PA 25.000000, PB 15.000000 and NOC 20.000000, with no carry, so each pays its own share."]'::jsonb, 0, 'The fixture gives EKO 40.000000, PA 25.000000, PB 15.000000 and NOC 20.000000 as participating interests, and states NOC carried 100 percent with carriers pro rata. The set 50.000000, 31.250000, 18.750000 and 0.000000 is the paying interests the engine computes from that carry. A half carry in stated shares is a separate worked case, and the fixture does state a carry.'),
  ('joa', 'beginner', 'module', 'm01-what-a-joint-operating-agreement-fixes', 8, 'Which of these does the engine decline to compute?', '["Each carrier''s carry points under a stated carry.", "The allowed overrun of a budget under its stated tolerance.", "An index adjustment of an overhead scale''s band limits.", "Each party''s forecast share of a month''s cash call."]'::jsonb, 2, 'The course lists what the engine does not compute: no compensation on an assignment, no cover by taking a defaulter''s petroleum, no index adjustment of a scale, no expert determination and no sliding scale of profit shares. Carry points, the allowed overrun of a budget and each forecast share are all figures the engine returns, from participatingInterests, budgetControl and cashCalls.'),
  ('joa', 'beginner', 'module', 'm01-what-a-joint-operating-agreement-fixes', 9, 'What code does jointVenture.js take from elsewhere in the engines package?', '["Its own npv and a Monte Carlo sampler, with calculatePartnerCosts imported from afe.js for splits.", "None at all: every split, pool and discount is its own code.", "applyPSC from cashflow.ts, with a partner split of its own kept in a helper beside the cash calls.", "applyPSC and npv from cashflow.ts, and calculatePartnerCosts from afe.js."]'::jsonb, 3, 'The engine''s two imports are engines/economics/cashflow.ts, for applyPSC and npv, and engines/economics/afe.js, for calculatePartnerCosts. It carries no cost pool, NPV or Monte Carlo code of its own, nothing in it samples, and every split of a joint account amount goes through the canonical calculatePartnerCosts.'),
  ('joa', 'beginner', 'module', 'm01-what-a-joint-operating-agreement-fixes', 10, 'What does the engine hand back when it refuses an input?', '["An object with error and field, whose message starts with the name of the field it refuses.", "A result whose figures are all zero, with a reason naming the field the engine doubted.", "The figures computed on the nearest accepted terms, with a warning printed in the basis.", "An empty result and a code number, which the panel looks up in a table of messages."]'::jsonb, 0, 'A refusal is an object with error and field: field names the input refused, and the message starts with that name and states the exact condition that failed, with the value it was given. A refusal returns no figures, so it hands back no zeros and no result on substitute terms, and the message is the engine''s own words with no code to look up.'),
  ('joa', 'beginner', 'module', 'm01-what-a-joint-operating-agreement-fixes', 11, 'On the Ekene 2027 cash calls, April and May make no cash call. How does the engine report those two months?', '["As a refusal naming noCallBelow, since the engine cannot compute a month that has no call.", "As a refusal naming the forecast of April, since a forecast of 0 is refused as an input.", "As a result, with a reason printed beside each month.", "As a result with both months left out of the ledger, and with no reason printed for them."]'::jsonb, 2, 'A result returned with a reason, such as a month with no cash call, is a result and no refusal. April''s forecast of 0 and May''s below 500000 are both below the stated threshold, and each month''s reason reads that there is no cash call and that the actual is billed in arrears in the next month. The months stay in the ledger, and a forecast of 0 is accepted.'),
  ('joa', 'beginner', 'module', 'm01-what-a-joint-operating-agreement-fixes', 12, 'A box states the carry under the key carry, singular. What does participatingInterests do with it?', '["It reads carry as carries, since the engine accepts the singular form of every plural key it knows.", "It refuses the key, naming it and listing the keys it accepts at the top level: parties, carries.", "It drops carry without a word and returns the paying interests as though no carry had been stated.", "It refuses the call for want of carries, naming carries as a required term with no default."]'::jsonb, 1, 'Every call refuses an input key the function does not read, naming the key, its path and the accepted keys. In the engine''s own words: carry is not an accepted key; the accepted keys at the top level are parties, carries. A misspelt key is refused, so a term is never dropped silently. The refusal names carry: carries itself is optional, and the worked case with no carry states none.'),
  ('joa', 'beginner', 'module', 'm01-what-a-joint-operating-agreement-fixes', 13, 'Why does every graded figure in this course have exactly one right answer?', '["Each figure is rounded to whole dollars by the grader, so any difference between machines disappears.", "Nothing in the engine samples or searches, so the same terms give the same number on any machine.", "The engine seeds its Monte Carlo sampler with a fixed seed that the capstone card states for each run.", "The capstone accepts the digits a reason prints, whichever of the two precisions the panel shows."]'::jsonb, 1, 'Every graded number is a return value of the engine on fixed inputs, and nothing in the engine samples or searches, so there is exactly one right answer. The engine has no Monte Carlo code of its own, so there is no seed. Each graded figure is quoted to six decimals as the panel prints it, which is neither whole dollars nor a reason''s digits.'),
  ('joa', 'beginner', 'module', 'm01-what-a-joint-operating-agreement-fixes', 14, 'Where does an Associate learner run the practicals of this course?', '["In a Suite app for joint ventures, opened from the Suite dashboard.", "In the recovery calculator, shared with the Professional tier.", "In a spreadsheet the learner builds, since an engine course carries no panel of its own.", "In the account calculator, the course''s own panel, which calls the vendored engine."]'::jsonb, 3, 'This is an engine course with no Suite app. Each tier has a calculator panel that calls the same vendored engine: the account calculator at Associate, the recovery calculator at Professional and the agreement calculator at Expert. The recovery calculator belongs to the Professional tier, and the panels make a spreadsheet unnecessary.'),
  ('joa', 'beginner', 'module', 'm01-what-a-joint-operating-agreement-fixes', 15, 'In this course the word overhead carries a narrower meaning than it has in conversation. What is it?', '["The operator''s charge on a stated scale over a stated base.", "Any indirect cost of the joint venture, charged at whatever figure the operator books for it.", "Every cost outside the approved budget, charged against the stated unbudgeted allowance.", "The part of a carried party''s cost share that its carriers pay on its behalf each month."]'::jsonb, 0, 'The course''s vocabulary legislates overhead as the operator''s charge on a stated scale over a stated base, and notes that the Norwegian scale it follows is a research and development and corporate charge. Any indirect cost is the conversational meaning the rule narrows. Spending outside the budget is tested against the unbudgeted allowance, and the cost share paid by carriers is a carry.'),
  ('joa', 'beginner', 'module', 'm02-participating-interests', 1, 'On the worked case int-ekene-no-carry, the four Ekene parties are stated with no carry. What paying interests does the engine return?', '["EKO 50.000000, PA 31.250000, PB 18.750000 and NOC 0.000000.", "EKO 40.000000, PA 25.000000, PB 15.000000 and NOC 20.000000.", "EKO 47.500000, PA 27.500000, PB 15.000000 and NOC 10.000000, as a half share of NOC''s cost moves.", "EKO 59.807692, PA 40.192308, PB 0.000000 and NOC 0.000000, with two parties paying for all four."]'::jsonb, 1, 'With no carry, the paying interest equals the participating interest, so the engine returns 40.000000, 25.000000, 15.000000 and 20.000000. The set with NOC at 0.000000 is the Ekene carry, the set with NOC at 10.000000 is the half carry in stated shares, and the set with PB and NOC both at 0.000000 is the case with two carries.'),
  ('joa', 'beginner', 'module', 'm02-participating-interests', 2, 'Four parties are typed with participating interests that sum to 90. What does the engine return?', '["The participating interests rescaled to make up 100, with a reason printing the factor applied.", "The participating interests as typed, with the unassigned 10 points of cost left to the operator.", "A refusal naming parties[0].participatingPct, the first share it reads in the box.", "A refusal naming parties, with the sum it found."]'::jsonb, 3, 'The engine refuses, in its own words: parties must have participatingPct summing to 100; got a sum of 90. The field it names is parties, the whole set, and no single share is faulted. It rescales nothing, assigns no share to the operator and guesses no party: a refusal returns no figures at all.'),
  ('joa', 'beginner', 'module', 'm02-participating-interests', 3, 'How far from 100 may the participating interests sum and still be accepted?', '["1e-9, the engine convention DEFAULTS.SUM_TOLERANCE.", "0.5 of a point, so spreadsheet rounding passes.", "Nothing: the sum must equal 100 exactly.", "One whole point, since a contract never writes a share finer than a whole percent."]'::jsonb, 0, 'DEFAULTS.SUM_TOLERANCE is 1e-9, how far participating interests or carrier shares may sum from 100, an engine convention. A tolerance of 0.5 or of a whole point would accept a set of parties that does not make up the whole, and an exact test would refuse sums that differ only by floating point noise.'),
  ('joa', 'beginner', 'module', 'm02-participating-interests', 4, 'Two parties in one box are both given the id A. Which answer does the engine give?', '["Both are merged into one party with both shares.", "It renames the second A2 and says so in a reason.", "A refusal: parties[1].id must be an id no other party has.", "A refusal naming parties[0].id, the first of the two."]'::jsonb, 2, 'The engine refuses, in its own words: parties[1].id must be an id no other party has; got "A". Its message names the second party''s path, parties[1].id, counting from zero, and leaves the first alone. It never merges, renames or drops a party, because each would compute on terms nobody stated.'),
  ('joa', 'beginner', 'module', 'm02-participating-interests', 5, 'A party''s participatingPct is typed as 0. What happens?', '["The party stays, with no share, and is called for nothing.", "The call is refused: a participating interest must be above 0 and at most 100.", "That party is dropped, and the others rescaled to 100.", "The party is treated as carried in full by the other parties, pro rata, for its whole share."]'::jsonb, 1, 'A party with no participating interest is no party to the venture, so the check on each party''s share comes before any split. The engine''s message names the first party''s path: parties[0].participatingPct must be a number above 0 and at most 100; got 0. Keeping a shareless party, rescaling the others or inventing a carry would each compute on terms nobody stated.'),
  ('joa', 'beginner', 'module', 'm02-participating-interests', 6, 'A spreadsheet labels the participating interest column wi, and the box keeps that key for each party. What does the engine do?', '["It reads wi as the participating interest, since that is the industry''s usual short name for it.", "It ignores wi and computes each party as though its participating interest were 0 in every month.", "It takes wi as the paying interest of each party.", "It refuses: a party''s accepted keys are id, name, participatingPct."]'::jsonb, 3, 'An unknown key is refused wherever it sits, with the full list of accepted keys. In the engine''s own words: parties[0].wi is not an accepted key; the accepted keys of parties[0] are id, name, participatingPct. The engine reads no alias, and it never drops a key and carries on.'),
  ('joa', 'beginner', 'module', 'm02-participating-interests', 7, 'The Norwegian joint operating agreement, Art. 8.1, fixes each party''s contribution to the joint venture''s funds by what?', '["Its participating interest at the licence''s grant date.", "The production it lifted in the month before.", "Its participating interest at the time the payment is made.", "The budget share it voted for in committee."]'::jsonb, 2, 'Art. 8.1 of the Norwegian agreement reads that the amount to be contributed by each party shall be calculated in accordance with the participating interest at the time the payment is made. The date of the licence, a month''s lifting and a committee vote are none of them the measure the article states.'),
  ('joa', 'beginner', 'module', 'm02-participating-interests', 8, 'Which code splits a joint account amount between the parties?', '["The canonical calculatePartnerCosts of engines/economics/afe.js.", "A split inside jointVenture.js for cash calls alone.", "The applyPSC function of cashflow.ts, run with a royalty of 0 and no cost oil limit.", "The npv of cashflow.ts at a discount rate of 0."]'::jsonb, 0, 'Every joint account amount the engine splits between parties goes through the canonical calculatePartnerCosts of engines/economics/afe.js. The engine''s basis says every split of a joint account amount is calculatePartnerCosts from engines/economics/afe.js on the paying interests. applyPSC and npv are imported from cashflow.ts for PSC cost recovery and discounting, and neither splits an amount between parties.'),
  ('joa', 'beginner', 'module', 'm02-participating-interests', 9, 'Under the Ekene carry, NOC carried in full by pro rata carriers, January 2027 forecasts 4000000.000000. What is PB''s forecast share?', '["600000.000000, on its participating interest of 15.000000 in the joint venture.", "675000.000000, its share of January''s actual.", "1250000.000000, on a paying interest of 31.250000 under the Ekene carry.", "750000.000000, on its paying interest of 18.750000."]'::jsonb, 3, 'January''s forecast of 4000000.000000 splits as EKO 2000000.000000, PA 1250000.000000, PB 750000.000000 and NOC 0.000000 on the paying interests. 675000.000000 is PB''s actual share, and 1250000.000000 is PA''s share on its paying interest of 31.250000. Splitting on PB''s participating interest of 15.000000 would ignore the carry that raises its paying interest to 18.750000.'),
  ('joa', 'beginner', 'module', 'm02-participating-interests', 10, 'Which share does the engine use when it splits production between the parties?', '["The paying interests, as for every joint account amount.", "The beneficial interests, through the same calculatePartnerCosts.", "The carriers'' shares, as they paid for the barrels.", "The paying interests of the month of lifting."]'::jsonb, 1, 'Every split goes through the canonical calculatePartnerCosts, on the paying interests for cost and the beneficial interests for production. The carriers pay a carried party''s cost share, and a carry moves cost and never moves production, so the carried party keeps its whole production share.'),
  ('joa', 'beginner', 'module', 'm02-participating-interests', 11, 'What is the most parties one call of the engine accepts?', '["20, the stated cap DEFAULTS.MAX_PARTIES.", "100, the cap DEFAULTS.MAX_YEARS on years, which also bounds the parties.", "200, the cap on budget items, cost categories and cost lines in one call.", "600, the cap on months in one cash call ledger, which also bounds parties."]'::jsonb, 0, 'DEFAULTS.MAX_PARTIES is 20, the most parties (and carries, and defaulters) one call accepts. 100 is DEFAULTS.MAX_YEARS, 200 is DEFAULTS.MAX_ITEMS for budget items, cost categories and cost lines, and 600 is DEFAULTS.MAX_MONTHS for one cash call ledger; none of the three bounds the parties.'),
  ('joa', 'beginner', 'module', 'm02-participating-interests', 12, 'What reason does the engine print for int-ekene-no-carry, the Ekene parties with no carry?', '["One line per party: paying equals participating.", "A line saying pro rata carriers were assumed.", "None: the engine returns no reason for that case.", "A warning that NOC, as the state participant, is usually carried by the others."]'::jsonb, 2, 'For int-ekene-no-carry the engine returns no reason. A carry prints a reason naming the carried party, its carried points and who pays them, and with no carry there is nothing to report. The engine assumes no carriers and prints no warning about a party it is not told is carried.'),
  ('joa', 'beginner', 'module', 'm02-participating-interests', 13, 'In the engine''s rule, which share always equals the participating interest?', '["The paying interest, the share of cost, whatever carry the agreement states.", "The carried part, when carried in full.", "The carry points each carrier pays, when its carriers share pro rata.", "The beneficial interest, the share of production."]'::jsonb, 3, 'The engine''s basis reads: beneficial interest = participating interest (the share of production); paying interest = participating interest - the carried part of a carried party''s share + the carriers'' shares of every carry. The paying interest moves under a carry, while the carried part and the carry points are the terms that move it.'),
  ('joa', 'beginner', 'module', 'm02-participating-interests', 14, 'Which inputs does participatingInterests read at the top level?', '["parties, carries and months.", "parties and carries.", "parties alone.", "parties, carries and an effective date."]'::jsonb, 1, 'The function table gives participatingInterests two inputs, parties and carries, and the engine''s refusal of an unknown key lists the same two: the accepted keys at the top level are parties, carries. Months belong to cashCalls, and an input key the function does not read, such as a date, is refused.'),
  ('joa', 'beginner', 'module', 'm02-participating-interests', 15, 'NOC is carried in full on the Ekene terms, and a partner report splits the January 2027 cash call on the participating interests. Which party does that split call for a cost it does not bear?', '["NOC, whose paying interest is 0.000000 while it is carried in full.", "EKO, whose paying interest as operator is 40.000000.", "PB, whose paying interest is 15.000000 under the carry.", "PA, whose paying interest stays at 25.000000."]'::jsonb, 0, 'Under the Ekene carry the paying interests are EKO 50.000000, PA 31.250000, PB 18.750000 and NOC 0.000000, so NOC''s forecast share of January is 0.000000. A split on the participating interests calls NOC for 20 percent of a cost it does not bear. EKO, PA and PB pay more than their participating interests, 50.000000, 31.250000 and 18.750000.'),
  ('joa', 'beginner', 'module', 'm03-paying-and-beneficial-interests', 1, 'NOC is carried in full on the Ekene terms. Which pair of figures does the engine return for it?', '["Beneficial 0.000000 and paying 20.000000, the carriers taking its barrels.", "Beneficial 0.000000 and paying 0.000000 until the carry is repaid.", "Beneficial 20.000000 and paying 0.000000.", "Beneficial 10.000000, paying 10.000000."]'::jsonb, 2, 'On int-ekene NOC''s beneficial interest is 20.000000, its share of production, and its paying interest 0.000000, its share of cost while it is carried. A carry moves cost and never moves production, so NOC''s production share stays whole: the carriers take none of its barrels. On the half carry in stated shares NOC''s paying interest is 10.000000 while its beneficial interest stays 20.000000.'),
  ('joa', 'beginner', 'module', 'm03-paying-and-beneficial-interests', 2, 'Under the Ekene carry, NOC carried in full by pro rata carriers, how many of NOC''s carried points does EKO pay, and what paying interest does that give EKO?', '["10.000000 points, for a paying interest of 50.000000.", "12.307692 points, for a paying interest of 59.807692.", "7.500000 points, for a paying interest of 47.500000.", "20.000000 points, all of them, as the operator."]'::jsonb, 0, 'The Ekene carry puts NOC''s 20 points on EKO, PA and PB pro rata to their participating interests: EKO 10.000000, PA 6.250000 and PB 3.750000. EKO''s paying interest is its 40.000000 plus 10.000000, or 50.000000. 12.307692 and 59.807692 come from the case with two carries, 7.500000 and 47.500000 from the half carry in stated shares, and the operator carries no more than its pro rata part.'),
  ('joa', 'beginner', 'module', 'm03-paying-and-beneficial-interests', 3, 'PA holds 25.000000 of the Ekene licence and shares the full carry of NOC''s 20 with the other payers pro rata. What paying interest does PA reach?', '["5.000000 points, a quarter of NOC''s twenty points, for a paying interest of 30.000000.", "31.250000: its 25.000000 plus 6.250000 carry points.", "2.500000 points, as in the half carry, for 27.500000.", "7.692308 points, as when PB is carried too, for 40.192308 in all."]'::jsonb, 1, 'The carriers share pro rata among the parties no carry names as carried, so PA takes 25 of the 80 points EKO, PA and PB hold, which is 6.250000 of NOC''s 20, and its paying interest is 31.250000. A quarter of twenty ignores that NOC''s own share is left out of the ratio. 2.500000 is PA''s part of the half carry in stated shares, and 7.692308 its part of NOC''s carry when PB is carried as well.'),
  ('joa', 'beginner', 'module', 'm03-paying-and-beneficial-interests', 4, 'The engine''s reason for the Ekene carry ends with a clause about NOC. Which clause is it?', '["it pays 20% once repaid", "its barrels pass to the carriers", "its beneficial interest falls to 0% while it is carried", "its share of production stays 20%"]'::jsonb, 3, 'The engine''s reason, in its own words, reads: NOC: 100% of its 20% cost share is carried (20 points), paid by EKO 10, PA 6.25, PB 3.75 (pro rata to their participating interests); its share of production stays 20%. NOC''s beneficial interest stays 20.000000 while it is carried, so no production passes to the carriers, and the reason says nothing about a repayment.'),
  ('joa', 'beginner', 'module', 'm03-paying-and-beneficial-interests', 5, 'On int-half-carry-stated, NOC is carried for 50.000000 percent of its cost share by EKO and PA. What is NOC''s paying interest?', '["0.000000: any carry relieves it of all its cost.", "10.000000: it pays the half of its share that is not carried.", "15.000000, the same as PB.", "20.000000: stated shares move only the carriers'' points."]'::jsonb, 1, 'Half of NOC''s 20 points of cost is carried, 10 points, so NOC still pays the other 10 itself: its paying interest is 10.000000, as the engine returns. A carry moves only the carried percentage stated, so 0.000000 would need a carry of 100 percent. 15.000000 is PB''s paying interest, and stated shares do move cost off the carried party.'),
  ('joa', 'beginner', 'module', 'm03-paying-and-beneficial-interests', 6, 'EKO takes 75.000000 and PA 25.000000 of a half carry of NOC''s cost. Whose paying interest equals its participating interest?', '["PA, at 25.000000: a carrier''s paying interest stays at its participating interest.", "NOC, at 20.000000: a half carry leaves the carried party''s share whole.", "PB, at 15.000000: the stated shares name only EKO and PA.", "EKO, at 40.000000."]'::jsonb, 2, 'The stated shares are EKO 75.000000 and PA 25.000000, so PB pays none of the carry and its paying interest stays 15.000000. PA''s paying interest is 27.500000 and EKO''s 47.500000, each raised by its carry points, and NOC''s falls to 10.000000.'),
  ('joa', 'beginner', 'module', 'm03-paying-and-beneficial-interests', 7, 'On int-half-carry-stated, EKO and PA carry 10 points of NOC''s cost in stated shares of 75.000000 and 25.000000. How many points does EKO pay?', '["7.500000, three quarters of the 10 carried points.", "15.000000, three quarters of NOC''s whole 20 points.", "10.000000, the points it pays under pro rata.", "5.000000, half of the 10 carried points."]'::jsonb, 0, 'The engine''s reason reads, in its own words: NOC: 50% of its 20% cost share is carried (10 points), paid by EKO 7.5, PA 2.5 (in the stated shares); its share of production stays 20%. The stated shares apply to the carried points, 10, so EKO''s 75 percent is 7.500000. Three quarters of 20 applies the shares to the part NOC still pays, 10.000000 is EKO''s pro rata part of a full carry, and a half ignores the stated shares.'),
  ('joa', 'beginner', 'module', 'm03-paying-and-beneficial-interests', 8, 'On int-two-carries NOC is carried in full pro rata, and PB is carried as well. Who carries NOC''s 20 points?', '["EKO, PA and PB, 10.000000, 6.250000 and 3.750000, as on the Ekene carry, with PB''s part paid by the others.", "EKO and PA in equal halves, 10.000000 each, following the stated halves of PB''s carry.", "EKO, PA and PB pro rata to their participating interests, PB included.", "EKO and PA alone: 12.307692 and 7.692308."]'::jsonb, 3, 'Pro rata carriers share a carry in proportion to their participating interests among the parties no carry names as carried. PB is carried, so NOC''s carriers are EKO and PA alone, in the ratio of their participating interests, and the engine returns 12.307692 and 7.692308. The equal halves are the stated shares of PB''s carry, which do not govern NOC''s.'),
  ('joa', 'beginner', 'module', 'm03-paying-and-beneficial-interests', 9, 'PB''s 15 points are carried in full by EKO and PA, half each, and NOC''s 20 by the uncarried parties pro rata. What paying interest does EKO reach?', '["50.000000, as on the Ekene carry.", "59.807692: 40 plus 12.307692 plus 7.500000.", "47.500000, as on the half carry in stated shares, EKO carrying 7.500000 of one carry.", "40.192308, its participating interest plus a share of each carry."]'::jsonb, 1, 'EKO''s paying interest is its participating interest of 40.000000 plus its carry points on both carries, NOC 12.307692 and PB 7.500000, which is 59.807692. 50.000000 is its figure under one carry, 47.500000 under the half carry, and 40.192308 is PA''s paying interest on int-two-carries.'),
  ('joa', 'beginner', 'module', 'm03-paying-and-beneficial-interests', 10, 'A carry is stated with carried and carriedPct but no carriers. What does the engine do?', '["It applies pro rata carriers and says so.", "A refusal naming carries[0].carriedPct.", "It refuses: the carriers must be stated, with no default.", "It leaves the carried party paying its own share, as though the carry had never been stated in the box."]'::jsonb, 2, 'The engine refuses, in its own words: carries[0].carriers must be "pro-rata" or an object of carrier shares in per cent (no default); got nothing. The field it names is carries[0].carriers; the carried percentage is stated. It chooses no carriers'' rule for the box and does not compute as if the carry were absent.'),
  ('joa', 'beginner', 'module', 'm03-paying-and-beneficial-interests', 11, 'Stated carrier shares of 60 and 30 are typed for a carry. What happens?', '["The engine refuses, printing the sum of 90 it found.", "The shares are rescaled pro rata to 100, and a reason says so.", "The missing 10 stays with the carried party.", "The missing 10 is spread over the parties the stated shares leave out, pro rata to their participating interests."]'::jsonb, 0, 'Stated shares must sum to 100. The engine refuses, in its own words: carries[0].carriers must sum to 100; got a sum of 90. It rescales nothing and assigns the missing 10 to nobody, because each would compute on a carry the agreement did not state.'),
  ('joa', 'beginner', 'module', 'm03-paying-and-beneficial-interests', 12, 'A second carry names NOC, itself carried, among its carriers. What is the engine''s answer?', '["Its part passes to its own carriers.", "It pays its part from its production.", "A refusal naming carries[1].carried.", "A refusal: a carried party cannot carry another."]'::jsonb, 3, 'The engine refuses, in its own words: carries[1].carriers.NOC is a carried party and cannot carry another. The field it names is the carrier, carries[1].carriers.NOC, and nothing is wrong with the party the second carry names as carried. It passes nothing on to other carriers and takes nothing from NOC''s production share.'),
  ('joa', 'beginner', 'module', 'm03-paying-and-beneficial-interests', 13, 'Someone types carriedPct as 0 when stating a carry. How does the engine answer?', '["It treats the carry as absent and returns the participating interests as the paying interests.", "It refuses, since carriedPct must be above 0 and at most 100.", "It treats 0 as no limit stated and carries the whole share.", "It accepts it with a reason: the party pays its whole share."]'::jsonb, 1, 'The carried percentage states how much of the carried party''s cost share moves to its carriers, so a figure of 0 states no carry at all and the engine refuses it. Its own words: carries[0].carriedPct must be a number above 0 and at most 100; got 0. Reading 0 as an absent carry or as a full one would compute on a term the agreement never stated.'),
  ('joa', 'beginner', 'module', 'm03-paying-and-beneficial-interests', 14, 'The carries of a box name every party as carried. What does the engine return?', '["The participating interests as the paying interests, since the carries cancel out.", "A refusal naming parties, as the carried shares leave no cost to split.", "A result in which the carries are applied in order, the last one dropped with a reason saying so.", "A refusal: at least one party must be left not carried."]'::jsonb, 3, 'A carry must leave at least one party paying. The engine refuses, in its own words: carries must be leaving at least one party that is not carried; got ["A","B"]. The field it names is carries, and the parties themselves are stated correctly. Carries do not cancel, and the engine drops no carry.'),
  ('joa', 'beginner', 'module', 'm03-paying-and-beneficial-interests', 15, 'The reason for int-two-carries prints EKO''s part of NOC''s carry with many more digits than the table''s 12.307692. Why?', '["A different carriers'' rule applies in the reason, so the two are different figures.", "The table rounds the figure after the carry is repaid, and the reason prints it before.", "Inside a message a percentage prints as the shortest round-trip decimal of the double the engine holds.", "The reason adds EKO''s stated share of PB''s carry to its part of NOC''s carry, so its figure is a sum."]'::jsonb, 2, 'The course prints every share to six decimals, so the field reads 12.307692, while inside a message a percentage or rate prints as the shortest round-trip decimal of the double the engine holds. Both come from the same pro rata rule and the same number, and the reason for NOC''s carry names only NOC''s carriers.'),
  ('joa', 'beginner', 'module', 'm04-cash-calls', 1, 'The Ekene 2027 cash calls state a reconciliation lag of 2 months. Which cash call does January 2027''s over-call adjust?', '["The February 2027 call, the first one made after January closes.", "The March 2027 call, two months later.", "The April 2027 call, the first month of the year without a call.", "The call of the next year."]'::jsonb, 1, 'The engine''s reason for March reads, in its own words: 2027-03: the over-call of 400000 in 2027-01 (forecast 4000000, actual 3600000) is credited against this cash call, 2 months later. The lag counts months from the month whose difference it is, so February is too soon, and April makes no call on the Ekene terms at all.'),
  ('joa', 'beginner', 'module', 'm04-cash-calls', 2, 'January''s differences reach the Ekene March calls. By how much is EKO''s call reduced?', '["400000.000000, January''s whole over-call.", "150000.000000, its June credit.", "125000.000000, PA''s January difference.", "200000.000000, its own January difference."]'::jsonb, 3, 'EKO''s January difference is its forecast share of 2000000.000000 less its actual share of 1800000.000000, which is 200000.000000, and that is the adjustment on its March row. 400000.000000 is the month''s difference over every party, split on the paying interests. 150000.000000 is EKO''s June adjustment, and 125000.000000 is PA''s January difference.'),
  ('joa', 'beginner', 'module', 'm04-cash-calls', 3, 'With the Ekene lag of 2 months, what is EKO''s March 2027 cash call?', '["5800000.000000, its forecast share less January''s difference.", "6000000.000000, its forecast share, unadjusted.", "5800000.000000 plus May''s arrears billing, since March pays arrears.", "4350000.000000."]'::jsonb, 0, 'EKO''s March forecast share is 6000000.000000 and its adjustment 200000.000000, so the call is 5800000.000000, and the table prints paid 5800000.000000 with an arrears billing of 0.000000. The forecast share alone ignores the lag, May''s actual is billed in arrears in June, and 4350000.000000 is EKO''s June call.'),
  ('joa', 'beginner', 'module', 'm04-cash-calls', 4, 'A worked case states a threshold of 500. January 2027 forecasts exactly 500 and February 499. Which months are called?', '["Neither month.", "Both months.", "January alone.", "February alone."]'::jsonb, 2, 'The rule is strictly below: a forecast equal to the threshold is called and one below it is not. On cc-threshold-exactly January is called for 500.000000 and February is not, and the engine''s reason reads: 2027-02: no cash call: the forecast 499 is below the stated threshold 500; the actual is billed in arrears in the next month. The test reads the forecast, and there is no margin of one.'),
  ('joa', 'beginner', 'module', 'm04-cash-calls', 5, 'On the Ekene terms, what does the no-call threshold of 500000 test?', '["The month''s actual, known only after the month has closed out.", "The month''s forecast, which is called unless below 500000.", "Each party''s forecast share against 500000.", "The call after its adjustment."]'::jsonb, 1, 'The engine''s basis reads: no cash call in a month whose forecast is below 500000; its actual share is billed in arrears the next month. The test reads the month''s forecast, since the call is made before the actuals are known, and it reads the whole month''s forecast. A call reduced below 500000 by its adjustment is still a call.'),
  ('joa', 'beginner', 'module', 'm04-cash-calls', 6, 'May 2027''s forecast is below the Ekene threshold of 500000, and the lag is 2 months. What does PB pay in June 2027?', '["1631250.000000, its June call; May waits for July.", "1687500.000000, its June forecast share.", "84000.000000, May''s arrears alone.", "1715250.000000, its call plus May''s arrears billing."]'::jsonb, 3, 'What a party pays in a month is its call plus its arrears billing. PB''s June call is 1631250.000000, its forecast share of 1687500.000000 less an adjustment of 56250.000000, and May''s actual is billed in arrears in June at 84000.000000 for PB, so it pays 1715250.000000. The engine''s reason reads: 2027-06: the actual of 2027-05, 448000, made without a cash call, is billed in arrears.'),
  ('joa', 'beginner', 'module', 'm04-cash-calls', 7, 'On cc-zero-call-month, with lag 1, negative call rule carry and no threshold stated, January over-calls by 200 and February forecasts 0. What happens in February and March?', '["February''s calls are -200.000000, a refund paid out at once, and March is then called in full at 400.000000.", "February makes no call, since a forecast of 0 is below any threshold, and the credit lapses at the month''s end.", "February''s calls are 0.000000, and the 200.000000 credit carries to March, whose calls are 200.000000.", "February''s calls are 0.000000, and the credit waits until the next year."]'::jsonb, 2, 'With no threshold stated, February is called with a forecast of 0.000000, and the call is the adjustment alone. Under carry, the engine''s reason reads: 2027-02: the adjustment exceeds the forecast share of A, B, C: the call is 0 and the rest of the credit is carried to the next cash call. March''s forecast of 400.000000 is reduced to calls of 200.000000. Paying the credit back at once belongs to the other stated rule, and this case states no threshold for February to fall under.'),
  ('joa', 'beginner', 'module', 'm04-cash-calls', 8, 'The same small case is run with the negative call rule stated as refund. What are February''s calls?', '["-200.000000, a negative call.", "0.000000, with 200.000000 carried to March''s call.", "200.000000, the credit paid back as a positive call to each party.", "0.000000, the excess held on account until the end of the year."]'::jsonb, 0, 'On cc-zero-call-month-refund the engine''s reason reads: 2027-02: the adjustment exceeds the forecast share of A, B, C: the excess is refunded (a negative call). February''s calls total -200.000000 and March is called in full at 400.000000. A zero call with the credit carried is the carry rule, and a refund is paid out as a negative call, so the sign is below zero.'),
  ('joa', 'beginner', 'module', 'm04-cash-calls', 9, 'On cc-year-boundary, December 2026 forecasts 1000 and spends 900, with a lag of 1. January 2027 forecasts 1000. What are January''s calls?', '["1000.000000: a new year starts the ledger afresh with no adjustment carried in.", "1100.000000, as an over-call adds.", "800.000000, credited twice.", "900.000000, after December''s credit."]'::jsonb, 3, 'The engine''s reason reads: 2027-01: the over-call of 100 in 2026-12 (forecast 1000, actual 900) is credited against this cash call, 1 month later. January''s forecast of 1000.000000 less the credit of 100 gives calls of 900.000000. The lag moves a difference across a year end with no special rule, and an over-call reduces a later call once.'),
  ('joa', 'beginner', 'module', 'm04-cash-calls', 10, 'A cash calls box leaves out reconciliationLagMonths. What does the engine do?', '["A refusal naming months, which it cannot read without a lag.", "It refuses: the lag must be an integer at or above 1.", "It computes every call with no adjustment and says so in a reason printed for each month.", "It applies each difference to the next call, as the Norwegian accounting agreement says."]'::jsonb, 1, 'The reconciliation lag is a contract term with no default. The engine refuses, in its own words: reconciliationLagMonths must be an integer at or above 1; got nothing. The field it names is reconciliationLagMonths, and the months are stated correctly. It assumes no lag, computes no calls without one, and reads no Norwegian wording into the box.'),
  ('joa', 'beginner', 'module', 'm04-cash-calls', 11, 'Can the reconciliation lag be stated as 0, so that a month''s difference adjusts its own call?', '["No: a lag of 0 is refused, the lag being an integer at or above 1.", "Yes: a lag of 0 adjusts each call by its own month''s difference.", "Yes, where the month''s actual is known before its call is paid.", "Only under the refund rule."]'::jsonb, 0, 'The engine refuses a lag of 0, in its own words: reconciliationLagMonths must be an integer at or above 1; got 0. The engine''s rule applies the difference of the month reconciliationLagMonths earlier, so the lag is stated as a whole number of months from 1 up, and a month''s own difference always adjusts a later call.'),
  ('joa', 'beginner', 'module', 'm04-cash-calls', 12, 'A box''s second month is typed as 2027-03, straight after 2027-01. What does the engine return?', '["A ledger with February filled in at a forecast and actual of 0, and a reason naming it.", "A refusal naming months[0].month, the month before the gap.", "A refusal naming months[1].month, which expected 2027-02.", "A result, with a reason printed that names the missing month."]'::jsonb, 2, 'The months must follow one another with no gap, because the lag counts months. The engine refuses, in its own words: months[1].month must be 2027-02, the month after 2027-01 (the months are consecutive); got "2027-03". It names the second month, months[1].month, the one that breaks the sequence, and fills in no month.'),
  ('joa', 'beginner', 'module', 'm04-cash-calls', 13, 'A cash calls box states negativeCall as net. What happens?', '["The credit is netted against the actual share.", "It is refused: the rule must be refund or carry.", "It is read as carry, the nearer of the two stated rules, and the credit waits for the next call.", "It is refused as a missing term: got nothing."]'::jsonb, 1, 'The negative call rule takes one of two stated values. The engine refuses, in its own words: negativeCall must be one of "refund", "carry"; got "net". The message prints the value it was given, "net", so the term was stated and is refused as a third word. It maps no third word onto either rule and mixes none of them.'),
  ('joa', 'beginner', 'module', 'm04-cash-calls', 14, 'On cc-last-month-uncalled, December 2027 forecasts 100 against a threshold of 500. What does the engine print for December?', '["A call of 100, since the last month of a ledger is always called in full.", "A refusal, since the ledger ends before any of the arrears can be billed.", "No cash call, with the actual billed in arrears in the next month.", "Calls of 120."]'::jsonb, 2, 'The engine''s reason reads: 2027-12: no cash call: the forecast 100 is below the stated threshold 500; the actual is billed in arrears in the next month. December''s calls are 0.000000. A last month gets no exception, the engine returns a result with a reason, and 120 is December''s actual, which is billed in arrears and never called.'),
  ('joa', 'beginner', 'module', 'm04-cash-calls', 15, 'January 2027 on the Ekene terms: forecast 4000000.000000, actual 3600000.000000. What is PA''s difference, and what kind is it?', '["125000.000000, an over-call: forecast share less actual share.", "125000.000000, an under-call it adds to its March call.", "400000.000000, the month''s whole over-call, credited to PA.", "1125000.000000, its actual share."]'::jsonb, 0, 'The difference is the forecast share less the actual share for a month with a call: PA''s 1250000.000000 less 1125000.000000 is 125000.000000, and above zero it is an over-call. An under-call is a difference below zero. 400000.000000 is the difference over every party, and 1125000.000000 is PA''s actual share.'),
  ('joa', 'beginner', 'module', 'm05-budget-control', 1, 'Geology and geophysics was approved at 6000000.000000 and spent 6600000.000000, under an item tolerance of 10.000000 percent. What does the engine return?', '["Beyond its tolerance: an overrun has to be strictly below the tolerance.", "Inside, only because the budget as a whole is inside its own tolerance.", "Inside its tolerance: an overrun of exactly the tolerance is inside.", "Beyond: the limit is 10 percent above the actual."]'::jsonb, 2, 'The engine''s boundary reads: an overrun of exactly the tolerance is inside ("may exceed ... by up to"). The limit is the approved amount raised by the tolerance, 6600000.000000, and the actual equals it, so the item is inside. The item test stands on its own, and the Ekene budget as a whole is beyond its tolerance. The limit is taken on the approved amount.'),
  ('joa', 'beginner', 'module', 'm05-budget-control', 2, 'What limit does the engine compute for exploration drilling, approved at 48000000.000000 under the Ekene 10 percent item tolerance?', '["52800000.000000, and the actual 53500000.000000 is beyond it.", "52800000.000000, and the actual is inside it by the item tolerance.", "53500000.000000, its actual.", "48000000.000000, as an item has no margin."]'::jsonb, 0, 'An item is inside its tolerance when actual <= approved x (100 + itemTolerancePct) / 100, so the limit is 52800000.000000 and the actual of 53500000.000000 is beyond it, an overrun of 11.458333 percent. The engine''s reason says so: exploration drilling: 53500000 against 48000000 approved is an overrun of 5500000, beyond the item tolerance of 10% (limit 52800000). The limit is computed from the approved amount, and the stated tolerance gives it a margin.'),
  ('joa', 'beginner', 'module', 'm05-budget-control', 3, 'The Ekene 2027 budget tolerance is the lower of 5.000000 percent and 3000000.000000, on an approved total of 76000000.000000. What is the allowed overrun?', '["3800000, 5 percent of the approved total, held by the percentage.", "3000000.000000 plus the unbudgeted allowance of 500000.000000.", "5950000.000000, the overrun the budget actually ran.", "3000000.000000, held by the amount."]'::jsonb, 3, 'The budget is inside when the total overrun <= the lower of pct % of the approved total and the stated amount. 5 percent of 76000000.000000 is 3800000, and the stated amount is 3000000, so the lower, 3000000.000000, holds, and the engine reports it held by amount. The unbudgeted allowance is a separate test, and 5950000.000000 is the overrun the allowed figure is compared with.'),
  ('joa', 'beginner', 'module', 'm05-budget-control', 4, 'Does the whole 2027 budget pass its own test, with 5.000000 percent and 3000000.000000 stated?', '["Yes: every item but exploration drilling is inside its item tolerance, so the budget is inside as well.", "No: its overrun of 5950000.000000 is beyond the allowed 3000000.000000.", "Yes: the overrun is tested against 5 percent of the actual total of 81950000.000000.", "Yes, once the survey''s 250000.000000 is taken out."]'::jsonb, 1, 'The engine returns an approved total of 76000000.000000, an actual of 81950000.000000, an overrun of 5950000.000000 and an allowed overrun of 3000000.000000, so the budget is beyond its tolerance. The budget test is separate from the item tests, it is taken on the approved total, and taking the survey''s 250000.000000 out would still leave an overrun far above 3000000.000000.'),
  ('joa', 'beginner', 'module', 'm05-budget-control', 5, 'A worked case states the budget tolerance as the lower of 5 percent and 75, in NOK million, on an approved budget of 2000. The overrun is 80. What does the engine return?', '["Beyond: the amount holds at 75.000000.", "Inside: the percentage holds at 100, and an overrun of 80 falls under it.", "Inside: the item is inside its 10 percent item tolerance, so the budget is too.", "The higher of the two limits holds, so it is inside."]'::jsonb, 0, 'On budget-norway-lower-of the engine''s reason reads: the budget: 2080 against 2000 approved, an overrun of 80; the allowed overrun is the lower of 5% of the approved total (100) and 75: 75; beyond the budget tolerance. The lower of 100 and 75 is 75, held by the amount. The item is inside its item tolerance, and the budget is still beyond.'),
  ('joa', 'beginner', 'module', 'm05-budget-control', 6, 'budget-norway-pct-holds approves 1000 and spends 1050, the lower of 5% and 75 again stated. How is that overrun judged?', '["Beyond: an overrun equal to the allowed overrun is beyond the budget tolerance.", "Inside: the amount holds at 75, which leaves the overrun of 50 well below it.", "Inside the budget tolerance, which the percentage holds at 50.000000 and the overrun equals.", "Beyond, because the overrun of 50 is set against 5 percent of the actual 1050."]'::jsonb, 2, 'On budget-norway-pct-holds the reason reads: the budget: 1050 against 1000 approved, an overrun of 50; the allowed overrun is the lower of 5% of the approved total (50) and 75: 50; inside the budget tolerance. The lower of 50 and 75 is 50, held by pct, and an overrun equal to it is inside. The percentage is taken on the approved total, and 5 percent of the actual would allow more.'),
  ('joa', 'beginner', 'module', 'm05-budget-control', 7, 'On budget-item-one-over, item x runs to 55.5 against 50 approved, at a stated 10 percent. How is it judged?', '["Inside: 55.5 rounds to 55, the limit, and exactly the limit is inside.", "A refusal: an actual above its limit is refused as an input.", "Inside, because 10 percent of the actual 55.5 is more than the overrun of 5.5.", "Beyond its tolerance: 5.5 of overrun against a limit of 55."]'::jsonb, 3, 'The engine''s reason reads: x: 55.5 against 50 approved is an overrun of 5.5, beyond the item tolerance of 10% (limit 55). The engine rounds nothing, an item beyond its tolerance is a result with a reason, and the limit is taken on the approved amount, so 55.5 is beyond 55.'),
  ('joa', 'beginner', 'module', 'm05-budget-control', 8, 'What does the engine return for budget-underrun, approved at 100 and spent 90?', '["A refusal: an actual below the approved amount is refused.", "An overrun of -10.000000, inside the budget tolerance.", "An overrun of 10.000000, the size of the gap.", "Beyond its tolerance: an underrun of 10 percent breaks a tolerance of 5 percent in the other direction."]'::jsonb, 1, 'The overrun is actual less approved, so an underrun is a negative overrun: -10.000000. The engine''s reason reads: the budget: 90 against 100 approved, an underrun of 10; the allowed overrun is 5% of the approved total, 5; inside the budget tolerance. An underrun is accepted, the sign is kept, and a tolerance limits overruns alone.'),
  ('joa', 'beginner', 'module', 'm05-budget-control', 9, 'The environmental baseline survey spent 250000.000000 with no approved budget, the only unbudgeted item, under an unbudgeted allowance of 500000.000000. What does the engine report?', '["Beyond its item tolerance, as any spend against 0 approved exceeds 10 percent of it.", "A refusal, since an item with an approved amount of 0 cannot be tested at all.", "Inside the unbudgeted allowance of 500000.000000, with 250000.000000 in all.", "Inside its item tolerance, at 0.000000 percent."]'::jsonb, 2, 'The engine''s reason reads: environmental baseline survey: 250000 spent with no approved budget, inside the unbudgeted allowance 500000 with the other unbudgeted items (250000 in all). An item with no approved budget is tested against the unbudgeted allowance, its overrun percent and limit print none, and nothing is refused.'),
  ('joa', 'beginner', 'module', 'm05-budget-control', 10, 'The unbudgeted allowance is stated as 249999 on the Ekene 2027 budget. What happens to the survey?', '["It is inside, since the allowance misses the survey by one dollar only.", "It is above the allowance, and the engine lists it among the items outside their tolerance.", "The engine refuses an allowance below the unbudgeted total.", "It moves into the approved budget, raising the approved total to cover it."]'::jsonb, 1, 'On budget-ekene-allowance-short the reason reads: environmental baseline survey: 250000 spent with no approved budget: the unbudgeted items total 250000, above the allowance 249999, and the items outside their tolerance are exploration drilling and environmental baseline survey. One dollar over is over, the allowance is accepted as stated, and the approved total stays 76000000.000000.'),
  ('joa', 'beginner', 'module', 'm05-budget-control', 11, 'No unbudgetedAllowance is stated for the Ekene 2027 budget. What does the engine print for the survey?', '["A refusal naming unbudgetedAllowance as a required term.", "Inside: with no allowance stated, there is no limit.", "Nothing: the survey drops out of the budget when no allowance is stated.", "That it was spent with no approved budget and is outside the approved budget."]'::jsonb, 3, 'On budget-ekene-no-allowance the engine''s reason reads: environmental baseline survey: 250000 spent with no approved budget: outside the approved budget. The allowance is optional, so no refusal comes back, no allowance is no licence to spend, and the survey stays in the actual total of 81950000.000000.'),
  ('joa', 'beginner', 'module', 'm05-budget-control', 12, 'Suppose budgetTolerance is missing from the Ekene 2027 budget''s terms. How does budgetControl respond?', '["It refuses, naming budgetTolerance: the object { pct, amount } has no default.", "It tests the whole budget against the item tolerance of 10.000000 percent.", "It skips the budget test and returns only the item tests.", "It applies the lower of 5 percent and NOK 75 million from the Norwegian agreement."]'::jsonb, 0, 'The engine refuses, in its own words: budgetTolerance must be an object { pct, amount } (amount optional; no default); got nothing. It borrows no other tolerance, skips no test, and holds none of the Norwegian figures: each call states its own.'),
  ('joa', 'beginner', 'module', 'm05-budget-control', 13, 'The item tolerance is left out of a budget control box. How does the engine answer?', '["By testing each item at the Norwegian 10 percent, the figure Art. 12.5 prints.", "Each item is tested at 0 percent, so any overrun is beyond.", "With a refusal naming itemTolerancePct, which it received as nothing.", "With a refusal naming items, which it cannot test without it."]'::jsonb, 2, 'The engine refuses, in its own words: itemTolerancePct must be a finite number at or above 0; got nothing. The Norwegian 10 percent is the text''s figure, and the engine holds none of it; a tolerance of 0 would be a stated term, and the field it names is the tolerance, with the items stated correctly.'),
  ('joa', 'beginner', 'module', 'm05-budget-control', 14, 'The budget tolerance is typed as { pct: 5, amt: 3000000 }. What does the engine do?', '["It refuses amt, listing the accepted keys of budgetTolerance: pct, amount.", "It reads amt as amount, a common short form of the key.", "It drops amt and holds the allowed overrun by the percentage alone.", "It refuses budgetTolerance as missing its amount."]'::jsonb, 0, 'budgetTolerance reads two keys, and a shortened spelling of amount is caught at its own path: budgetTolerance.amt is not an accepted key; the accepted keys of budgetTolerance are pct, amount. Guessing that amt meant amount, or quietly holding by pct alone, would each compute a tolerance nobody stated, and the amount is optional, so its absence is never the fault: the refusal names the key amt.'),
  ('joa', 'beginner', 'module', 'm05-budget-control', 15, 'Facilities engineering spent 9200000.000000 of an approved 10000000.000000 in 2027. How does the item test read it?', '["An underrun that frees 800000.000000 for the overrun of exploration drilling, which comes inside.", "A refusal, since an actual below approved is no overrun at all and cannot be tested.", "Beyond its tolerance, as an underrun of 8 percent is a deviation from the approved line.", "-800000.000000, or -8.000000 percent, inside its item tolerance."]'::jsonb, 3, 'The overrun is actual less approved, -800000.000000, which is -8.000000 percent and inside any tolerance at or above zero. The engine tests each item against its own limit, so exploration drilling is still beyond its tolerance, and an underrun is a result.'),
  ('joa', 'beginner', 'module', 'm06-overhead-basics', 1, 'The Ekene 2031 operating cost is 60000000.000000, and 2000000.000000 of it is stated as excluded. Before any band is applied, how large is the operating base?', '["60000000.000000, since an exclusion reduces the charge after the scale has been applied.", "58000000.000000: the cost less the stated exclusion.", "50000000.000000, the part of the base that sits in the first band.", "58000000.000000 plus the overhead charged on it."]'::jsonb, 1, 'The engine''s basis reads: base = annual cost - stated exclusions. The operating cost is 60000000.000000 and 2000000.000000 is excluded, so the base is 58000000.000000, and the engine''s reason prints base 58000000 (cost 60000000 less exclusions 2000000). The exclusion comes out before the scale, 50000000.000000 is only the part inside band 1, and overhead charged under the scale is never part of its own base.'),
  ('joa', 'beginner', 'module', 'm06-overhead-basics', 2, 'The Ekene operating scale charges 2.75 per cent to 50000000.000000 and 1 per cent to 125000000.000000. What does it charge on the 2031 base of 58000000.000000?', '["1375000.000000, the charge of the first band alone.", "1343750.000000, the flat corporate charge.", "80000.000000, 1% of the part above 50000000.", "1455000.000000: 2.75% of 50000000 plus 1% of 8000000."]'::jsonb, 3, 'The scale is marginal: each band''s per cent on the part of the base inside the band. The engine''s reason reads: operating: base 58000000 (cost 60000000 less exclusions 2000000); 2.75% of 50000000 + 1% of 8000000 = 1455000. 1375000.000000 and 80000.000000 are the two band charges taken one at a time, and 1343750.000000 is the flat 0.625000 percent charge on all three categories together.'),
  ('joa', 'beginner', 'module', 'm06-overhead-basics', 3, 'The Ekene 2031 development base of 150000000.000000 runs through bands of 2.5, 1 and 0.5 per cent ending at 50000000.000000, 100000000.000000 and 175000000.000000. What is the development charge?', '["2000000.000000, band by band.", "1250000.000000, the first band''s charge.", "3580000.000000, the charge over all three categories.", "500000.000000, the second band''s charge alone."]'::jsonb, 0, 'The engine''s reason reads: development: base 150000000; 2.5% of 50000000 + 1% of 50000000 + 0.5% of 50000000 = 2000000. 1250000.000000 and 500000.000000 are the first and second bands'' own charges, and 3580000.000000 is the total over the exploration, operating and development categories.'),
  ('joa', 'beginner', 'module', 'm06-overhead-basics', 4, 'On their Ekene 2031 scales, exploration is charged 125000.000000, operating 1455000.000000 and development 2000000.000000, with no corporate charge stated. What total overhead does the engine return?', '["1343750.000000, the flat corporate charge, which takes the place of the category scales.", "2000000.000000, the development charge, the largest of the three categories.", "3580000.000000.", "1455000.000000."]'::jsonb, 2, 'The three category charges are exploration 125000.000000, operating 1455000.000000 and development 2000000.000000, and the engine returns a total overhead of 3580000.000000. The flat corporate charge of 1343750.000000 is a separate golden case, and 2000000.000000 and 1455000.000000 are single categories.'),
  ('joa', 'beginner', 'module', 'm06-overhead-basics', 5, 'The Ekene corporate charge is a flat 0.625000 percent. How does the engine state a flat percentage?', '["As one band whose upTo is set equal to the base, at its pct.", "Under the key flat, which the scale accepts for a single rate.", "As an exclusion equal to the base less the charge.", "As a scale with no bands, the whole base charged at abovePct."]'::jsonb, 3, 'The engine''s basis reads: a flat percentage is a scale with no bands. With no bands, the whole base is charged at abovePct, as on overhead-ekene-2031-corporate: exploration, operating and development: base 215000000; 0.625% of 215000000 = 1343750. A scale reads only bands and abovePct, so a key named flat is refused, and a band would need its upTo restated for every base.'),
  ('joa', 'beginner', 'module', 'm06-overhead-basics', 6, 'The Norwegian accounting agreement, Art. 2.2.3, prints 0.65 % of the annual costs for exploration, operation and development. On a base of 3400 NOK million, what does the engine charge?', '["65.450000.", "22.100000.", "35.000000.", "42.500000."]'::jsonb, 1, 'On overhead-norway-corporate-065 the engine''s reason reads: exploration, operation and development: base 3400; 0.65% of 3400 = 22.1, a total of 22.100000. The other three figures are cases of the Art. 2.2.2 research and development scale: 65.450000 over three categories with an exclusion, 35.000000 on an operating base of 1800 and 42.500000 on a development base of 4000.'),
  ('joa', 'beginner', 'module', 'm06-overhead-basics', 7, 'overhead-band-edge-exact states an operating base of 1000 on a scale whose first band ends at 1000, at 2.7%. Where is the base charged?', '["All 1000.000000 in the first band and 0.000000 in the second: 27.000000.", "In the second band, since a base at the limit has passed into the next band.", "Split at the edge, the last unit in the second band.", "At the second band''s rate on the whole base."]'::jsonb, 0, 'A base exactly at a band''s upper limit is charged in that band only: overhead-band-edge-exact charges 1000.000000 in the first band and 0.000000 in the second, a total of 27.000000, and the reason reads: operating: base 1000; 2.7% of 1000 = 27. Nothing crosses the edge, and the scale is marginal, so no rate applies to the whole base.'),
  ('joa', 'beginner', 'module', 'm06-overhead-basics', 8, 'A worked case states the Norwegian development scale in NOK million, 2.5 per cent to 1000, 1 per cent to 2000 and 0.5 per cent to 3500, with 0 stated above the last band, on a base of 4000. What does the engine charge?', '["40.000000: the printed scale stops at 3000.", "100.000000, 2.5 per cent of the whole base of 4000.", "42.500000, with nothing charged on the 500 above 3500.", "35.000000, as for the operating scale on 1800."]'::jsonb, 2, 'The engine''s reason reads: development: base 4000; 2.5% of 1000 + 1% of 1000 + 0.5% of 1500 + 0% of 500 above 3500 = 42.5. The bands run to 3500, where 40.000000 is the charge on a base of 3000, the first band''s 2.5 per cent covers only its first 1000, and 35.000000 belongs to the operating scale.'),
  ('joa', 'beginner', 'module', 'm06-overhead-basics', 9, 'A Norwegian worked case excludes 150 of area fees and CO2 duty from an operating cost of 1000 NOK million, on a scale of 2.7 per cent up to 1000 and 1 per cent on the next band. What is the operating charge?', '["27 on the whole cost of 1000, at 2.7%.", "22.95 on a base of 850, at 2.7%.", "22.1 on a base of 3400, at the flat 0.65%.", "65.450000, the charge over all three categories of that case."]'::jsonb, 1, 'On overhead-norway-all-with-exclusion the reason reads: operating: base 850 (cost 1000 less exclusions 150); 2.7% of 850 = 22.95. The exclusion comes out of the base before the scale, so 27 on the whole 1000 is wrong. 22.1 is the flat 0.65% corporate case on a base of 3400, and 65.450000 is that case''s total over three categories.'),
  ('joa', 'beginner', 'module', 'm06-overhead-basics', 10, 'Can overhead charged under a scale enter the base it is charged on?', '["Yes: each year''s charge is added to the next year''s base.", "Yes, under a marginal scale, as each band''s charge feeds the next band.", "Only under a flat percentage, where the base and charge are one.", "No: the engine''s basis and Norway Art. 2.2.2 both keep it out."]'::jsonb, 3, 'The engine''s basis reads: overhead charged under the scale is never part of its own base. The Norwegian accounting agreement says the same: "Cost charged to the Joint Account in accordance with this Article is not to be included in the basis of calculation." (Norway Accounting Agreement Art. 2.2.2). Neither a marginal scale nor a flat percentage makes an exception.'),
  ('joa', 'beginner', 'module', 'm06-overhead-basics', 11, 'The Norwegian accounting agreement moves its band limits each year with the consumer price index. What does the engine do with a scale?', '["No index adjustment: it applies the limits the call states.", "Each limit is moved by the index per 15 July.", "It adjusts them once a base year is stated.", "It refuses a scale that comes with no index series."]'::jsonb, 0, 'The Norwegian Art. 2.2.2 moves its intervals each year by the consumer price index as published by Statistics Norway per 15 July of the current year. The engine computes no index adjustment of a scale: it applies the band limits each call states, so a later year''s scale is stated with that year''s limits. It reads no index and refuses nothing for want of one.'),
  ('joa', 'beginner', 'module', 'm06-overhead-basics', 12, 'The operating scale is deleted from the Ekene 2031 overhead box. What does the engine do?', '["It charges operating at the exploration scale, the nearest category it holds.", "Operating is charged at 0, since no scale was stated.", "It refuses, naming scale.operating: there is no default rate.", "It refuses, naming costs.operating as a cost with no scale."]'::jsonb, 2, 'The engine refuses, in its own words: scale.operating must be an object { bands, abovePct } (no default rate); got nothing. The field it names is the scale, scale.operating; the cost is stated correctly. It borrows no scale from another category or from the Norwegian text.'),
  ('joa', 'beginner', 'module', 'm06-overhead-basics', 13, 'A scale''s second band is given the same upTo as the first, 100. How does the engine answer?', '["By merging the two bands and charging the merged band at the higher of their two per cents.", "By treating the second band as empty and charging the base above it at abovePct.", "The bands are sorted.", "With a refusal: each band''s upTo must be above the one before."]'::jsonb, 3, 'The engine refuses, in its own words: scale.operating.bands[1].upTo must be above the previous band''s upTo 100; got 100. It merges, empties and sorts nothing: a scale is charged exactly as it is stated or not at all.'),
  ('joa', 'beginner', 'module', 'm06-overhead-basics', 14, 'An exclusion of 11 is stated on an operating cost of 10. What happens?', '["The engine refuses: an exclusion may not exceed its category''s cost.", "The base is clipped at 0, and nothing is charged for operating.", "A negative base of -1 gives a small credit to the parties.", "It refuses, naming costs.operating as too small for its exclusion."]'::jsonb, 0, 'The engine refuses, in its own words: excluded.operating must be at or below the cost of the category 10; got 11. The field it names is the exclusion, excluded.operating, measured against the stated cost. A base cannot fall below zero by an exclusion.'),
  ('joa', 'beginner', 'module', 'm06-overhead-basics', 15, 'A scale lists its bands and leaves out abovePct. What happens?', '["The part above the last band is charged at the last band''s per cent.", "It is refused: abovePct is required even when it is zero.", "The part above the last band is left uncharged, as the Norwegian text prints nothing there.", "It is refused for a missing bands list."]'::jsonb, 1, 'The engine refuses, in its own words: scale.operating.abovePct must be a number from 0 to 100; got nothing. The Norwegian scale prints nothing above its last band, so the worked cases state 0 there; the engine extends no band''s per cent, and the bands are listed, so abovePct alone is refused.'),
  ('joa', 'beginner', 'final', null, 1, 'How does the course give the edition of the Kenya Model Production Sharing Contract''s Participation Agreement?', '["The 2015 model, its file name dated 21 January 2015.", "The 2013 model of TPDC, read from a Wayback Machine capture of 23 May 2024.", "An unofficial English translation dated 27 February 2007.", "November 2007, marked Public Disclosure Authorized."]'::jsonb, 0, 'The sources table gives the Kenya Participation Agreement as the 2015 model, with its file name dated 21 January 2015, read on 2026-09-26. The 2013 model read from the capture of 23 May 2024 is Tanzania''s TPDC agreement, the 2007 unofficial translation is the Norwegian agreement, and November 2007 is World Bank Briefing Note 8.'),
  ('joa', 'beginner', 'final', null, 2, 'The course quotes 56 provisions from its public texts. Which text in its sources table has none of them?', '["The Kenya Model Production Sharing Contract, Participation Agreement.", "World Bank Petroleum Sector Briefing Note No. 8.", "The Tanzania Model Production Sharing Agreement 2013 (TPDC).", "OpenOil, Oil Contracts: How to read and understand them, version 1."]'::jsonb, 2, 'The count of quoted provisions reads: PIA 11, NOJOA 14, NOAA 10, KENYA 9, WB 5, FARI 3, IMFWP 2, OPENOIL 2, which makes 56. The Tanzania model is read as concept only, a cost recovery limit, a contractor loan and an overhead cap, and none of its sentences is quoted. Kenya has 9 quoted provisions, the World Bank note 5 and OpenOil 2.'),
  ('joa', 'beginner', 'final', null, 3, 'Which of these is a legal figure the engine applies from an Act, cited to its section?', '["The item tolerance of 10 percent, which Norway JOA Art. 12.5 fixes for every call.", "The no-call threshold of 500000.000000 the Ekene fixture applies.", "DEFAULTS.SUM_TOLERANCE, 1e-9, a limit the Act sets on how far participating interests may sum from 100.", "PIA_JV.maxGovernmentParticipationPct, 60.000000, from PIA s.85(4)(a)."]'::jsonb, 3, 'The engine''s stated constants cite PIA_JV.maxGovernmentParticipationPct, 60.000000, to PIA s.85(4)(a), applied only under basis "pia-s85-4". The Norwegian 10 percent is the text''s figure and a stated input, the 500000.000000 is a term of the synthetic Ekene contract, and DEFAULTS.SUM_TOLERANCE is an engine convention with no Act behind it.'),
  ('joa', 'beginner', 'final', null, 4, 'What does the engine export under the name ACCEPTED_KEYS?', '["A list of aliases, such as wi, that it maps onto participatingPct.", "One shape of accepted keys for each of its 9 functions.", "The keys of the Ekene fixture file, for the panels to load at start.", "A table of error codes, one code for each of the 78 refusals the course lists."]'::jsonb, 1, 'ACCEPTED_KEYS is exported with one shape for each of the 9 functions, and every call refuses an input key its function does not read, at every level. The engine maps no alias onto a key it reads, the fixture is a separate file, and a refusal is an object with error and field, carrying a message in words and no code.'),
  ('joa', 'beginner', 'final', null, 5, 'Six items make up the Ekene 2027 budget. How many could a single budgetControl call take?', '["20, the cap DEFAULTS.MAX_BANDS on the bands of one overhead scale.", "600, the cap DEFAULTS.MAX_MONTHS on one ledger''s months.", "200, DEFAULTS.MAX_ITEMS, shared with cost categories and cost lines.", "100, the cap DEFAULTS.MAX_YEARS."]'::jsonb, 2, 'Budget items share their cap with cost categories and cost lines: DEFAULTS.MAX_ITEMS, 200. The bands of one overhead scale are capped separately at 20, one ledger''s months at 600 and one call''s years at 100, and none of those three limits a budget''s items.'),
  ('joa', 'beginner', 'final', null, 6, 'What does a cash call computed by the engine tell you, and what does it leave unsaid?', '["What the stated forecast and clauses produce; it forecasts no partner''s payment.", "What each partner will in fact pay the operator that month, after any default.", "The operator''s forecast of spending, corrected by the engine to the likely actual.", "A forecast of next month''s actual spending."]'::jsonb, 0, 'The course says a cash call is what the stated forecast and the stated clauses produce, and that none of the computed figures is a forecast of what a partner will pay; each is quoted with its terms for that reason. The engine corrects no forecast and predicts no actual: it computes on the figures the box states.'),
  ('joa', 'beginner', 'final', null, 7, 'When the course quotes an overhead charge, what does it quote beside the figure?', '["The operator''s name and the year''s approved budget, since overhead is charged against it.", "Its scale and its exclusions.", "The paying interests that will split it, as each party''s share of the charge.", "Its NPV at a stated rate and base year."]'::jsonb, 1, 'The course''s vocabulary says a figure that depends on a term is quoted with it: a call with its lag and negative call rule, an overrun with its tolerance, an overhead charge with its scale and exclusions. The charge depends on the scale and the base after exclusions, and an NPV belongs to other figures and other courses.'),
  ('joa', 'beginner', 'final', null, 8, 'A credit on a cash call waits for a later call. How does the course''s vocabulary say that?', '["The credit is a carry of the party that was over-called in that month.", "The credit is that party''s premium on the next call.", "The credit is held as the over-called party''s carried interest.", "The credit is carried to the next cash call."]'::jsonb, 3, 'The vocabulary keeps carry for a carried party''s cost share paid by its carriers; a pool, a credit or a balance moved to a later period is carried forward or carried to a named period. A premium is the stated multiple of a non-consenting party''s proportionate share, and a carried interest is a share of the venture, so neither names a waiting credit.'),
  ('joa', 'beginner', 'final', null, 9, 'In the course''s vocabulary, what is an adjustment?', '["An earlier month''s difference applied to a later cash call.", "A change the committee makes to an approved line.", "A correction of a party''s participating interest.", "The overhead charged on a month''s actual spending."]'::jsonb, 0, 'The vocabulary defines a cash call as the operator''s monthly request for advances against a forecast, and an adjustment as the difference of an earlier month applied to a later call. Budget lines, participating interests and overhead are each governed by their own rules and none is called an adjustment.'),
  ('joa', 'beginner', 'final', null, 10, 'The fixture plants April and May 2027 with no cash call and May''s actual billed in June. Which engine behaviour finds that situation?', '["The cashCalls adjustment, which credits January''s over-call in March.", "The cashCalls threshold and arrears billing.", "The budgetControl item boundary.", "The cashCalls rule for a negative call carried to the following month''s call."]'::jsonb, 1, 'The table of planted situations pairs "April (forecast 0) and May (below the threshold) make no call; May''s actual is billed in June" with cashCalls threshold and arrears. The adjustment finds January''s over-call credited in March, the item boundary finds geology and geophysics, and a negative call carried finds September.'),
  ('joa', 'beginner', 'final', null, 11, 'Name PA''s call once the lag of 2 months brings January''s credit into March 2027.', '["3750000.000000, its March forecast share, with January''s difference settled in February.", "3625000.000000 plus a share of May''s arrears.", "2175000.000000.", "3625000.000000: 3750000.000000 less January''s 125000.000000."]'::jsonb, 3, 'PA''s paying interest of 31.250000 gives a March forecast share of 3750000.000000, and its January difference of 125000.000000 reaches March under the lag of 2 months, so its call is 3625000.000000 and it pays 3625000.000000 with no arrears billing. May''s actual is billed in June, and 2175000.000000 is PB''s March call.'),
  ('joa', 'beginner', 'final', null, 12, 'Sum up PA''s June 2027 payment on the Ekene terms, a lag of 2 months and a threshold of 500000.', '["2858750.000000: its call of 2718750.000000 plus 140000.000000.", "2718750.000000, its June call, with May''s actual left for July.", "2812500.000000, its June forecast share before the adjustment comes off.", "140000.000000, May''s arrears billing alone, with the June call deferred."]'::jsonb, 0, 'PA''s June row prints forecast share 2812500.000000, adjustment 93750.000000, call 2718750.000000, arrears billing 140000.000000 and paid 2858750.000000: the payment adds May''s billing to the June call. July plays no part, and the forecast share is the figure before the credit comes off.'),
  ('joa', 'beginner', 'final', null, 13, 'NOC, carried in full on the Ekene terms, holds a beneficial interest of 20.000000. What does NOC pay in June 2027?', '["20 percent of May''s arrears, since arrears follow the beneficial interest.", "Its share of the June call, the carry ending once a threshold month passes.", "0.000000 across call, arrears billing and paid.", "Nothing in June, as it settles every call at the end of the year."]'::jsonb, 2, 'Every cash call and arrears billing is split on the paying interests, and NOC''s is 0.000000 while it is carried in full, so its June row shows a call, arrears billing and paid of 0.000000. The beneficial interest is its share of production, the carry does not end with a threshold month, and nothing in the rule defers a party''s calls to the year''s end.'),
  ('joa', 'beginner', 'final', null, 14, 'Under the Ekene carry, May 2027''s actual of 448000 is billed in arrears in June. What is EKO''s arrears billing?', '["448000, the whole actual, billed to the operator.", "224000.000000, the actual split on its paying interest of 50.000000.", "140000.000000, the part billed to PA.", "84000.000000, split on EKO''s participating interest."]'::jsonb, 1, 'The engine''s reason reads: 2027-06: the actual of 2027-05, 448000, made without a cash call, is billed in arrears. The actual is split on the paying interests, so EKO''s arrears billing is 224000.000000, PA''s 140000.000000 and PB''s 84000.000000. The operator is billed only its own share.'),
  ('joa', 'beginner', 'final', null, 15, 'Kenya Model PSC 2015, Art. 6.4, has an advance above the month''s disbursements reduce the next succeeding cash advance. Which engine term fixes which later call it reduces?', '["noCallBelow, the threshold set against the month the advance was made.", "negativeCall, picking the month and the rule.", "itemTolerancePct, for any advance above budget.", "reconciliationLagMonths, a stated lag with no default."]'::jsonb, 3, 'The engine''s rule applies the difference of the month reconciliationLagMonths earlier, and the lag is a contract term with no default. The threshold decides whether a month is called at all, negativeCall decides what happens when a credit exceeds a call, and the item tolerance belongs to budget control.'),
  ('joa', 'beginner', 'final', null, 16, 'The Norwegian accounting agreement has the operator refund excess amounts unless the parties agree to transfer them to the following period. Where does that choice sit in the engine?', '["In negativeCall, stated as refund or carry.", "In reconciliationLagMonths, stated as 1 for a refund.", "In noCallBelow, where a month below the threshold refunds its excess.", "In budgetTolerance, for excess amounts beyond the approved total."]'::jsonb, 0, 'Norway Accounting Agreement Art. 1.2.1 prints both choices, and the engine takes the choice as negativeCall, one of "refund" or "carry", a required term. The lag fixes which later call a difference adjusts, the threshold decides whether a month is called, and the budget tolerance tests spending against a budget.'),
  ('joa', 'beginner', 'final', null, 17, 'To book a credit note, a clerk enters -1 as a month''s actual. What comes back?', '["Booked as a credit, the -1 raises that month''s difference by one.", "It treats -1 as a missing actual and bills it in arrears in the following month.", "months[0].actual is refused; only figures at or above 0 are accepted.", "It clips the actual at 0 and says so."]'::jsonb, 2, 'The engine refuses, in its own words: months[0].actual must be a finite number at or above 0; got -1. It clips nothing and books no negative spending, and a missing actual has no meaning in the rule: each month states its forecast and its actual.'),
  ('joa', 'beginner', 'final', null, 18, 'A months entry carries a budget figure beside its forecast and actual. What does the engine return?', '["A ledger that tests each month''s actual against that budget figure.", "A ledger computed as usual, the budget figure dropped without a word.", "A refusal naming months, as a month may carry two figures.", "A refusal listing a month''s keys: month, forecast, actual."]'::jsonb, 3, 'The engine refuses, in its own words: months[0].budget is not an accepted key; the accepted keys of months[0] are month, forecast, actual. The field it names is the key itself, months[0].budget. Budget control is a separate function with its own items, and the engine never drops a key silently or swaps one figure for another.'),
  ('joa', 'beginner', 'final', null, 19, 'A cash calls box states its reconciliation lag under the key lag. What does the engine say?', '["It reads lag as reconciliationLagMonths.", "It refuses lag and lists its six accepted top-level keys.", "It ignores lag and makes no adjustment.", "It refuses the box for a missing lag."]'::jsonb, 1, 'The engine refuses the unknown key first, in its own words: lag is not an accepted key; the accepted keys at the top level are parties, carries, months, reconciliationLagMonths, negativeCall, noCallBelow. It reads no short form, and it computes nothing with an unknown key in the box.'),
  ('joa', 'beginner', 'final', null, 20, 'Someone drops the leading zero and types January 2027 as 2027-1. How does cashCalls respond?', '["A refusal: a month must be written ''YYYY-MM''.", "The month read as January 2027, the leading zero supplied for it.", "The month read as October 2027, from the digits 2027-1 and a zero after them.", "A refusal naming months[1].month, the month after it."]'::jsonb, 0, 'The engine refuses, in its own words: months[0].month must be a month ''YYYY-MM''; got "2027-1". It names the month it cannot read, months[0].month, and supplies no digit and guesses no month.'),
  ('joa', 'beginner', 'final', null, 21, 'Why is every adjustment in January 2027 on the Ekene terms 0.000000?', '["January''s forecast is below the stated threshold of 500000, so no call is made.", "The negative call rule carry holds every credit until the end of the quarter.", "NOC is carried.", "No month lies a lag of 2 months before January in the ledger."]'::jsonb, 3, 'The call is the forecast share less the difference of the month reconciliationLagMonths earlier plus any amount carried, and the Ekene ledger starts in January 2027, so January has nothing to apply: every adjustment is 0.000000 and each call equals its forecast share, EKO''s 2000000.000000. January''s forecast of 4000000.000000 is above the threshold, carry holds a credit only until the next call, and NOC''s carry only makes its own row zero.'),
  ('joa', 'beginner', 'final', null, 22, 'Where does operations support, 8300000.000000 spent on 8000000.000000 approved, stand against its 10 percent item limit?', '["Beyond, as any overrun on an approved line needs the committee''s fresh approval.", "Inside, an overrun of 3.750000 percent against a limit of 8800000.000000.", "Inside, since the limit is set 10 percent above its actual spend of 8300000.000000.", "Beyond, as the budget as a whole is beyond its tolerance."]'::jsonb, 1, 'The engine''s reason reads: operations support: 8300000 against 8000000 approved is an overrun of 300000, inside the item tolerance of 10% (limit 8800000). The overrun percent is 3.750000. The limit is taken on the approved amount, an item inside its tolerance needs no fresh approval, and the budget test is separate from the item test.'),
  ('joa', 'beginner', 'final', null, 23, 'General and administration was approved at 4000000.000000 and spent 4100000.000000 under a 10 percent item tolerance. What limit and overrun percent does the engine return?', '["Limit 4100000.000000 and 10.000000 percent.", "Limit 4400000.000000 and 10.000000 percent, exactly at the tolerance.", "Limit 4400000.000000 and 2.500000 percent, inside.", "Limit 4000000.000000, 2.500000 percent beyond."]'::jsonb, 2, 'The limit is approved x (100 + itemTolerancePct) / 100, 4400000.000000, and the overrun of 100000 is 2.500000 percent of the approved amount, so the item is inside. 10.000000 percent is the tolerance itself, reached exactly by geology and geophysics, and an item''s limit carries the stated margin.'),
  ('joa', 'beginner', 'final', null, 24, 'On which total does the engine take the percentage of the budget tolerance?', '["The approved total.", "The actual total.", "The largest approved item.", "The approved total less the unbudgeted items."]'::jsonb, 0, 'The engine''s rule reads: the budget is inside when the total overrun <= the lower of pct % of the approved total and the stated amount. On the Ekene 2027 budget the reason prints 5% of the approved total (3800000), on 76000000.000000. The actual total, 81950000.000000 on the Ekene 2027 budget, and the largest item, exploration drilling at 48000000.000000, are no part of the test, and an unbudgeted item has an approved amount of 0.'),
  ('joa', 'beginner', 'final', null, 25, 'With the 10 percent item tolerance and no unbudgeted allowance stated, which Ekene 2027 items does the engine list as outside their tolerance?', '["Exploration drilling alone, since an unbudgeted item has no tolerance to be outside.", "Exploration drilling and geology and geophysics.", "Every item, the budget being beyond its tolerance.", "Exploration drilling and environmental baseline survey."]'::jsonb, 3, 'On budget-ekene-no-allowance the engine lists exploration drilling and environmental baseline survey as the items outside their tolerance, the survey''s reason reading that it was spent with no approved budget: outside the approved budget. Geology and geophysics sits exactly on its limit and is inside, and the budget''s own verdict does not move any item.'),
  ('joa', 'beginner', 'final', null, 26, 'The Norwegian agreement allows work outside the programme and the budgets up to NOK 3 million a budget in the year. How does the engine hold such an allowance?', '["As a fixed NOK 3 million, which it converts to US$ for the Ekene budget.", "As unbudgetedAllowance, stated by the call and tested against the unbudgeted items together.", "As part of the budget tolerance, added to its stated amount for the year''s test.", "As one extra item approved at the allowance and tested at the item tolerance."]'::jsonb, 1, 'The engine holds none of the Norwegian figures, and each call states its own. The Ekene 2027 budget states an unbudgeted allowance of 500000.000000, and the survey''s reason tests it with the other unbudgeted items (250000 in all). The allowance is a test of its own, separate from the budget tolerance, and nothing is converted from NOK.'),
  ('joa', 'beginner', 'final', null, 27, 'On budget-item-at-tolerance, item x spends 55 against 50 approved, with 10 percent stated for the item and for the budget. What does the budget test return?', '["Beyond: meeting the allowed overrun is beyond.", "Inside, held by the amount, since the case states one.", "Inside: an overrun of 5 against an allowed 5, held by pct.", "Beyond: 10 percent of the actual 55 is allowed."]'::jsonb, 2, 'Here budgetTolerance states a percentage alone, so pct holds, and 10% of the approved 50 allows 5, which the overrun of 5 meets. In the engine''s words: the budget: 55 against 50 approved, an overrun of 5; the allowed overrun is 10% of the approved total, 5; inside the budget tolerance. No amount is stated to hold it, and the actual plays no part in the allowance.'),
  ('joa', 'beginner', 'final', null, 28, 'Where does the engine''s source for budgetControl say the percentages and amounts come from, after citing Norway JOA Art. 12.5?', '["From Art. 12.5 itself, which the engine holds as its standing figures.", "The Ekene fixture, which states them for every budget.", "From the operating committee''s approved budget.", "Every percentage and amount is an input the call states."]'::jsonb, 3, 'The engine''s basis.source for budgetControl ends: every percentage and amount is a stated input with no default. The Norwegian 10 percent and the lower of 5 percent and NOK 75 million are the text''s figures, and the Ekene fixture''s figures are the terms of one synthetic contract.'),
  ('joa', 'beginner', 'final', null, 29, 'overhead-norway-operating-1800 states the Art. 2.2.2 operating scale as 2.7 per cent up to 1000 and 1 per cent on a second band that reaches past 1800. Which charge does it produce on a base of 1800?', '["35.000000: 2.7% of 1000 plus 1% of 800.", "27.000000, the first band alone.", "1% of the whole base of 1800.", "40.000000, the development scale."]'::jsonb, 0, 'The engine''s reason reads: operating: base 1800; 2.7% of 1000 + 1% of 800 = 35. The scale is marginal, so the first band''s 27.000000 is only part of the charge, the band the base ends in charges only its own part, and 40.000000 belongs to the development scale on a base of 3000.'),
  ('joa', 'beginner', 'final', null, 30, 'overhead-norway-development-3000 runs a development base of 3000 through bands of 2.5 per cent to 1000, 1 per cent to 2000 and 0.5 per cent to 3500. What total comes back?', '["42.500000, the charge on 4000 with 500 above the last band.", "40.000000, over the three bands.", "35.000000, as for the operating scale.", "30.000000, 1% of the whole base."]'::jsonb, 1, 'The engine''s reason reads: development: base 3000; 2.5% of 1000 + 1% of 1000 + 0.5% of 1000 = 40. 42.500000 is the charge on a base of 4000, 35.000000 is the operating scale on 1800, and the marginal scale charges no single rate on the whole base.'),
  ('joa', 'beginner', 'final', null, 31, 'The Norwegian exploration scale, 2.5% in a single band up to 300, is stated on a base of 250 NOK million. What does the engine charge?', '["7.5, the charge on a base of 400.", "0.000000, as a base below the first band''s limit is not charged.", "6.250000, at 2.5% inside the first band.", "25.000000, 10 percent of 250."]'::jsonb, 2, 'The engine''s reason reads: exploration: base 250; 2.5% of 250 = 6.25. The whole base sits inside the first band, which charges its per cent on the part inside it. 7.5 is the exploration charge on a base of 400 in another case, where 100 lies above the last band at 0%.'),
  ('joa', 'beginner', 'final', null, 32, 'overhead-zero-cost states an operating cost of 0. What does the engine return?', '["A refusal, since a category with no cost cannot carry a scale.", "A minimum charge of the first band''s per cent on the band''s full width.", "A charge of 27.000000.", "A charge of 0: the base is 0 and there is nothing to charge."]'::jsonb, 3, 'The engine''s reason reads: operating: base 0; nothing to charge = 0, a total of 0.000000. A zero cost is a result, the scale is marginal so an empty band charges nothing, and 27.000000 is the band edge case on a base of 1000.'),
  ('joa', 'beginner', 'final', null, 33, 'To state a flat charge, a box gives scale.operating as { flat: 0.65 }. What happens?', '["The whole operating base is charged at 0.65 per cent, the flat key''s rate.", "It is refused: a scale reads only bands and abovePct.", "The flat key is read as a single band reaching to the base.", "A charge of 22.100000."]'::jsonb, 1, 'The engine refuses, in its own words: scale.operating.flat is not an accepted key; the accepted keys of scale.operating are bands, abovePct. A flat percentage is stated as a scale with no bands, the whole base charged at abovePct. 22.100000 is the 0.65% case on a base of 3400.'),
  ('joa', 'beginner', 'final', null, 34, 'An exclusion is stated for a category named drilling, and the box''s costs hold only operating. What does the engine do?', '["It refuses: drilling is not a cost category.", "It takes the exclusion off the operating base.", "It keeps the exclusion aside until a drilling cost is stated in a later year''s box.", "It ignores the unknown category and charges operating in full."]'::jsonb, 0, 'The engine refuses, in its own words: excluded.drilling is not a cost category; the categories are operating. An exclusion belongs to the category it names, and a name that matches no category is refused, and is neither moved, held nor ignored.'),
  ('joa', 'beginner', 'final', null, 35, 'The Ekene 2031 exploration base is 5000000.000000 on a scale whose single band charges 2.5% to 30000000.000000, with 0 above. What is charged above the last band?', '["125000.000000, the whole exploration charge.", "30000000.000000, the band''s width, at 0 per cent.", "0.000000, as the base stays below the band''s upper limit.", "The rest of the base at the first band''s 2.500000 per cent."]'::jsonb, 2, 'The exploration base of 5000000.000000 sits inside band 1, where 2.5% of 5000000 = 125000, and the part of the base above the last band is 0.000000, charged 0.000000. 125000.000000 is band 1''s charge, the band''s width is no part of the base, and a base inside the first band is charged at that band''s per cent.'),
  ('joa', 'beginner', 'final', null, 36, 'Which text and articles does the engine''s source cite for its overhead?', '["Norway JOA Art. 12.5, the budget article, with its NOK 3 million.", "Kenya Model PSC 2015, Participation Agreement Art. 6.2 and 6.4.", "Norway Accounting Agreement Art. 1.2.1 and 1.2.2, the cash articles.", "Norway Accounting Agreement Art. 2.2.2 and Art. 2.2.3."]'::jsonb, 3, 'The engine''s basis.source for overhead cites Attachment B, the Accounting Agreement, Art. 2.2.2 (per cent rates and limits on annual exploration, operating and development cost, with stated exclusions) and Art. 2.2.3 (0.65 % of the annual costs). Art. 12.5 is cited for budget control, Art. 1.2.1 for cash calls, and the Kenya articles are cash call clauses.'),
  ('joa', 'beginner', 'final', null, 37, 'The cash calls view prints a Source block under its result. What does it name?', '["Kenya Model PSC 2015, Art. 6.7 alone.", "Attachment B Art. 1.2.1, with Attachment A Art. 8.1.", "PIA s.85(4), the carried interest provision.", "Norway JOA Art. 12.5, with the NOK 3 million."]'::jsonb, 1, 'The engine''s basis.source for cashCalls cites Attachment B Accounting Agreement Art. 1.2.1 and Attachment A Joint Operating Agreement Art. 8.1. PIA s.85(4) is cited with participatingInterests, Art. 12.5 with budgetControl, and the Kenya text is not the source the engine names for its cash calls.'),
  ('joa', 'beginner', 'final', null, 38, 'Suppose both NOC and PB are carried whole: NOC''s 20 split pro rata among the uncarried, PB''s 15 split equally by EKO and PA. What share of cost falls on PA?', '["40.192308: its 25 plus 7.692308 of NOC''s carry and 7.500000 of PB''s.", "31.250000, the same as under the Ekene carry alone.", "27.500000, as under the half carry in stated shares.", "59.807692, EKO''s figure."]'::jsonb, 0, 'With PB carried, NOC''s 20 points fall on EKO and PA alone in the ratio 40 to 25, so PA''s part is 7.692308, and PA also pays half of PB''s 15, 7.500000. Added to its own 25 that makes 40.192308, as the engine returns on int-two-carries. PA pays 31.250000 when NOC alone is carried pro rata and 27.500000 under the half carry in stated shares, and 59.807692 belongs to EKO.'),
  ('joa', 'beginner', 'final', null, 39, 'NOC is carried for 50.000000 percent of its cost share by EKO and PA in stated shares of 75.000000 and 25.000000. How much of each cost does PA bear?', '["31.250000, as PA''s pro rata part of the carry.", "25.000000, since a carrier''s paying interest stays put.", "35.000000, 25 plus the whole 10 carried points.", "27.500000: 25 plus 2.500000 carry points."]'::jsonb, 3, 'The half carry moves 10 points of NOC''s cost to EKO and PA in stated shares of 75.000000 and 25.000000, so PA pays 2.500000 points and its paying interest is 27.500000, as the engine returns. 31.250000 is PA''s figure under the full pro rata carry, a carrier''s paying interest rises by its points, and PA takes only its stated 25 percent of the 10 carried points.'),
  ('joa', 'beginner', 'final', null, 40, 'IMF WP/24/89 (April 2024) describes what a carry is. What does it say?', '["A transfer of the state''s share of production to the parties that carry it.", "A tax credit the state grants its carriers on the development spending they cover.", "A financing arrangement to cover the state''s proportional share of development spending.", "A premium the state pays its carriers on its proportional share of development costs."]'::jsonb, 2, 'The working paper reads: "The parties may establish a financing arrangement to cover (“carry”) the state’s proportional share of development spending." (IMF WP/24/89 (April 2024)). A carry finances cost, and the engine''s rule leaves the carried party''s share of production whole.'),
  ('joa', 'beginner', 'final', null, 41, 'Under PIA s.85(4), which contract must include a carried interest provision?', '["A production sharing contract under s.85(2)(a), for the risk-bearing party.", "A concession agreement under s.85(2)(d), which may include a joint venture with NNPC Limited.", "Every contract under section 85, whatever its form, including production sharing.", "A renegotiated production sharing contract under s.311(2)(a)(iii), with its cost oil limit."]'::jsonb, 1, 'Section 85(4) opens "A contract as provided for under section 85 (2) (d)", which is the concession agreement that may include an incorporated or unincorporated joint venture with NNPC Limited. A production sharing contract is s.85(2)(a), and s.311(2)(a)(iii) sets the cost oil limit of a renegotiated one, a different provision.'),
  ('joa', 'beginner', 'final', null, 42, 'What does the capstone of each tier state about its joint venture?', '["The Ekene terms with one figure changed, so the rehearsal carries straight over.", "Only the parties, leaving the learner to choose the other terms.", "The terms, plus a tolerance the learner may apply to any figure.", "Every term a figure depends on, in a synthetic joint venture of its own."]'::jsonb, 3, 'Each capstone runs its own synthetic joint venture, which the course does not print, and states every term a figure depends on, from the parties and their participating interests to the overhead scale and exclusions. It is not built from the Ekene terms, it leaves no term to the learner, and each graded figure is quoted to six decimals as the panel prints it.');
